function dictionaryFrom(locale: Locale, copy: LocaleCopy): Dictionary {
  if (copy.nav.length !== navKeys.length || copy.landing.length !== landingKeys.length || onboardingCopy[locale].length !== onboardingKeys.length) {
    throw new Error("locale dictionary does not match the registered key shape");
  }
  return {
    status: { partial: copy.partial },
    onboarding: Object.fromEntries(onboardingKeys.map((key, index) => [key, onboardingCopy[locale][index]])) as Dictionary["onboarding"],
    nav: Object.fromEntries(navKeys.map((key, index) => [key, copy.nav[index]])) as Dictionary["nav"],
    landing: Object.fromEntries(landingKeys.map((key, index) => [key, copy.landing[index]])) as Dictionary["landing"],
  };
}

export const dictionaries: Record<Locale, Dictionary> = Object.fromEntries(
  LOCALES.map((locale) => [locale, dictionaryFrom(locale, copy[locale])]),
) as Record<Locale, Dictionary>;

export function getDictionary(locale: Locale): Dictionary {
  return dictionaries[locale];
}
